<?php // Managed by clamshield
$automatic_labels=['report'=>'Report only','quarantine'=>'Quarantine detected files','cleanup'=>'Clean recognized infections','cleanup-or-quarantine'=>'Clean recognized infections; quarantine unsupported files'];
$automatic_allowed=static function($mode) use ($data){$required=['report'=>[],'quarantine'=>['automatic','quarantine'],'cleanup'=>['automatic','cleanup'],'cleanup-or-quarantine'=>['automatic','cleanup','quarantine']];foreach(($required[$mode]??[]) as $key){if(!$data['website_permissions']['effective'][$key])return false;}return true;}; ?>
<section data-page="automatic" hidden><h2>Automatic website actions</h2>
<p>Set global or account defaults and override individual websites. Accounts inherit global defaults until an override is saved. Settings apply to scans queued after saving. Only complete ClamAV and YARA scans can trigger an action. Integrity checks and restore/undo rechecks do not trigger automatic actions.</p>
<form data-capability="automatic" class="cs-automatic-policy" data-scope="<?=$cs_global?'server':'account'?>"><div class="row cs-controls-row"><label><?=$cs_global?'Global default':'Account default'?> <select class="form-select" name="mode"><?php if(!$cs_global): ?><option value="inherit" <?=$data['remediation_policy']['account']['mode']==='inherit'?'selected':''?>>Use global default</option><?php endif ?><?php foreach($automatic_labels as $value=>$label): ?><option value="<?=$value?>" <?=$automatic_allowed($value)?'':'disabled'?> <?=$data['remediation_policy']['account']['mode']===$value?'selected':''?>><?=$escape($label)?></option><?php endforeach ?></select></label> <button class="button" type="submit">Save <?=$cs_global?'global':'account'?> actions</button></div><p role="status" aria-live="polite"></p></form>
<div class="scroll"><table><thead><tr><th>Website</th><th>Policy</th><th>Effective action</th></tr></thead><tbody>
<?php foreach($data['sites'] as $site): ?><tr data-owner="<?=$escape($cs_owner($site))?>"><td><?=$escape($cs_label($site))?></td><td><?php if(isset($site['remediation']['error'])): ?><?=$escape($site['remediation']['error'])?><?php else: ?><form data-capability="automatic" class="cs-automatic-policy" data-scope="site" data-domain="<?=$escape($site['domain'])?>"><div class="row cs-controls-row"><label>Website actions <select class="form-select" name="mode"><option value="inherit" <?=$automatic_allowed($data['remediation_policy']['account']['mode'])?'':'disabled'?> <?=$site['remediation']['site']['mode']==='inherit'?'selected':''?>>Use account default</option><?php foreach($automatic_labels as $value=>$label): ?><option value="<?=$value?>" <?=$automatic_allowed($value)?'':'disabled'?> <?=$site['remediation']['site']['mode']===$value?'selected':''?>><?=$escape($label)?></option><?php endforeach ?></select></label> <button class="button" type="submit">Save website actions</button></div><p role="status" aria-live="polite"></p></form><?php endif ?></td><td><?=$escape($automatic_labels[$site['remediation']['effective']['mode']??'report'])?><?php if(!empty($site['remediation']['effective']['blocked_reason'])): ?><br><?=$escape($site['remediation']['effective']['blocked_reason'])?><?php endif ?><?php if(($site['remediation']['effective']['authority']??'')==='administrator'): ?><br>Configured by administrator<?php endif ?></td></tr><?php endforeach ?>
</tbody></table></div>
<p>Cleaning retains the original and a diff, validates the proposed file with both engines, and verifies the published bytes with a new scan. Unsupported infections stay open under Clean recognized infections. The combined mode quarantines unsupported files; engine errors and changed content require review. File cleaning does not establish that an entire site or database is clean.</p>
<p>Policy changes, current exceptions and cancellation stop pending actions. An action already moving or publishing a file completes recovery; use restore or undo afterward. Restored files receive a scan without repeating the automatic action.</p>
</section>
<script>
document.querySelectorAll('.cs-automatic-policy').forEach(form=>form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button'),status=form.querySelector('[role="status"]');button.disabled=true;status.textContent='Saving automatic actions…';try{const response=await fetch(location.pathname,{method:'POST',credentials:'same-origin',body:new URLSearchParams({token:<?=json_encode($_SESSION['token']??'',JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,owner:form.closest('[data-owner]')?.dataset.owner||<?=json_encode($data['context']['owner'],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,action:'remediation-policy-save',scope:form.dataset.scope,domain:form.dataset.domain||'',policy:JSON.stringify({mode:new FormData(form).get('mode')})})});const result=await response.json();if(!response.ok||!result.ok)throw new Error(result.error||'Policy could not be saved');location.reload();}catch(error){status.textContent=error.message;button.disabled=false;}}));
</script>
